'use strict';
/* COHORT standalone client demonstration. All financial and invitation operations are simulated. */
const VERSION=1, STORE='cohort-client-preview-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((Number(n)||0)/100);
const uuid=()=>globalThis.crypto?.randomUUID?.()||('d-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
const slugify=s=>String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const commission=(amount,rate)=>Math.round(amount*rate/100);
const rupees=s=>{if(!/^\d+(\.\d{1,2})?$/.test(String(s).trim()))throw new Error('Enter a valid non-negative amount with at most two decimal places.');const [a,b='']=String(s).split('.');const amount=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount>10000000000)throw new Error('Amount is too large for this demo.');return amount};
const net=t=>t.gross-t.refunded-t.commission+t.commissionReversed;
function refundTransaction(t,amount){if(!Number.isSafeInteger(amount)||amount<=0||amount>t.gross-t.refunded)throw new Error('Refund must be greater than zero and no more than the remaining payment.');const refunded=t.refunded+amount;return {...t,refunded,commissionReversed:refunded===t.gross?t.commission:commission(refunded,t.rate)}}
const svgPaths={layers:'<path d="m12 3 10 5-10 5L2 8l10-5Z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',book:'<path d="M12 7v14M3 3h6a3 3 0 0 1 3 3 3 3 0 0 1 3-3h6v16h-6a3 3 0 0 0-3 2 3 3 0 0 0-3-2H3Z"/>',shop:'<path d="m6 3-3 4v14h18V7l-3-4ZM3 7h18M8 11a4 4 0 0 0 8 0"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',credit:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 10h20M6 15h4"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-5h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3Z"/>',chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8Z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M16 7V3H8v4M3 12a22 22 0 0 0 18 0M12 11v4"/>',shield:'<path d="m12 3 9 4v5c0 5-9 10-9 10S3 17 3 12V7l9-4Z"/><path d="m8 12 3 3 5-6"/>',activity:'<path d="M3 12h4l3-9 4 18 3-9h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M7 17 17 7M7 7h10v10"/>',chevron:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',check:'<path d="m4 12 5 5L20 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',circle:'<circle cx="12" cy="12" r="9"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',play:'<path d="m8 4 13 8-13 8Z"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',send:'<path d="m22 2-7 20-4-9L2 9 20 2ZM22 2 11 13"/>',file:'<path d="M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 13h8M8 17h6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v5M8 21h8M10 18h4"/>'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgPaths[n]||svgPaths.layers}</svg>`;
const attrs=(action,id='',extra='')=>`data-action="${esc(action)}"${id!==''?` data-id="${esc(id)}"`:''}${extra}`;
const btn=(text,action,id='',variant='',ic='')=>`<button type="button" class="btn ${variant}" ${attrs(action,id)}>${ic?icon(ic,15):''}${text}</button>`;
const badge=(text,status='')=>`<span class="badge ${status}">${esc(text)}</span>`;
const navs={Agency:['Overview','Creators','Revenue','Packages','Agency services','Activity'],Creator:['Overview','Community','Classroom','Store','Memberships','Events','Members','Earnings','Settings'],Member:['Community','Classroom','Store','Memberships','Events','My account']};
const navIcon={Overview:'grid',Creators:'users',Revenue:'credit',Packages:'layers','Agency services':'briefcase',Activity:'activity',Community:'chat',Classroom:'book',Store:'shop',Memberships:'layers',Events:'calendar',Members:'users',Earnings:'credit',Settings:'settings','My account':'users'};
const kindIcon={Course:'book',Product:'shop',Membership:'layers',Event:'calendar'};
const seed=()=>({version:VERSION,workspaces:[{id:'ws-demo-a',name:'The Learning Collective',owner:'Demo Creator A',email:'creator-a@example.com',slug:'learning-collective',package:'Growth',setup:999900,monthly:69900,days:30,rate:7,status:'Active',billing:'Included access',description:'A shared space to learn, build and turn your expertise into something valuable.',created:new Date().toISOString()},{id:'ws-demo-b',name:'The Creative Studio',owner:'Demo Creator B',email:'creator-b@example.com',slug:'creative-studio',package:'Starter',setup:499900,monthly:69900,days:30,rate:7,status:'Active',billing:'Included access',description:'Make time for creative practice. Learn new skills and share your work with people who care.',created:new Date().toISOString()}],packages:[{id:'pkg-starter',name:'Starter',price:499900,description:'Community creation, branding and basic setup'},{id:'pkg-growth',name:'Growth',price:999900,description:'Community, courses, products and payment configuration'},{id:'pkg-premium',name:'Premium',price:1999900,description:'Complete setup, content upload and launch assistance'}],offers:[{id:'c-a',wid:'ws-demo-a',kind:'Course',title:'Build your first digital product',description:'Turn what you know into something people value. A practical, three-lesson path from idea to launch.',price:99900,published:true,planId:'m-a',modules:[{title:'From idea to offer',lessons:[{title:'Find a problem worth solving',body:'Start with a person, not a product. Describe one audience you understand, the challenge they face, and what they have already tried.\n\nYour action: write a one-sentence problem statement. Make it specific enough that a real person would recognise themselves in it.'},{title:'Design your first offer',body:'Choose the smallest useful outcome you can help someone achieve. Your first offer does not need to cover everything you know. It needs a clear promise, a manageable format, and a realistic path to a result.\n\nYour action: define the outcome, format and scope of your first product.'}]},{title:'Launch with intention',lessons:[{title:'Create your launch plan',body:'A useful launch is a conversation with your audience. Share the problem, explain your approach, invite questions and make the next step obvious.\n\nYour action: plan three messages: one about the problem, one about your method, and one inviting people to take the next step.'}]}]},{id:'c-free',wid:'ws-demo-a',kind:'Course',title:'Welcome to the collective',description:'Get your bearings, meet your community and set a learning goal you can actually follow through on.',price:0,published:true,planId:'',modules:[{title:'Start here',lessons:[{title:'Make yourself at home',body:'Welcome to your shared learning space. Start by exploring the community feed and introducing yourself.\n\nYour action: share what you are working on and one thing you hope to learn.'},{title:'Set one meaningful goal',body:'Choose one outcome for the next month. Keep it concrete, achievable and relevant to what matters to you.\n\nYour action: write down your goal, then choose one small action you can take today.'}]}]},{id:'p-a',wid:'ws-demo-a',kind:'Product',title:'Creator launch workbook',description:'A guided worksheet for shaping your audience, offer and first launch. Includes a downloadable demonstration workbook.',price:29900,published:true,planId:'m-a'},{id:'m-a',wid:'ws-demo-a',kind:'Membership',title:'Collective Plus',description:'A monthly home for your next chapter. Includes the digital-product course and creator launch workbook in this demo.',price:29900,published:true,planId:'',period:'Monthly'},{id:'e-a',wid:'ws-demo-a',kind:'Event',title:'From expertise to your first offer',description:'An interactive workshop for turning an idea into a clear, useful offer. Bring a question and leave with a next step.',price:49900,published:true,planId:'',date:'2026-12-05T18:00',duration:60,link:''},{id:'c-b',wid:'ws-demo-b',kind:'Course',title:'Creative foundations',description:'Find your creative direction and build a practice that lasts. This course belongs to the second demo workspace.',price:59900,published:true,planId:'',modules:[{title:'Your creative practice',lessons:[{title:'Find your direction',body:'Notice the work that makes you curious. Explore what it has in common and what you would like to make next.\n\nYour action: write a short creative brief for yourself.'},{title:'Build a small practice',body:'Make the next action small enough to repeat. Consistency starts with choosing a realistic time and place.\n\nYour action: schedule a 20-minute creative session.'}]}]}],members:[{id:'mem-a',wid:'ws-demo-a',name:'Demo Member',email:'member@example.com',role:'Member',status:'Active'},{id:'mem-b',wid:'ws-demo-b',name:'Demo Member',email:'member@example.com',role:'Member',status:'Active'}],posts:[{id:'post-a',wid:'ws-demo-a',author:'Demo Creator A',text:'Welcome to The Learning Collective. This is your space to share questions, small wins and the things you are building. Introduce yourself below, then explore the free welcome course.',pinned:true,likes:0,liked:false,comments:[],category:'Announcements',created:new Date().toISOString()},{id:'post-b',wid:'ws-demo-b',author:'Demo Creator B',text:'Welcome to The Creative Studio. What would you like to make this month? Share your idea and take the first step.',pinned:true,likes:0,liked:false,comments:[],category:'Announcements',created:new Date().toISOString()}],transactions:[],jobs:[],audit:[],progress:{},enrolled:[],registrations:[],cancelledRenewals:[],role:'Agency',wid:'ws-demo-a',page:'Overview'});
let storageAvailable=true,state;
try{const raw=localStorage.getItem(STORE);const parsed=raw?JSON.parse(raw):null;state=parsed?.version===VERSION&&Array.isArray(parsed.workspaces)&&parsed.workspaces.length?parsed:seed()}catch{storageAvailable=false;state=seed()}
let modal=null,fields={},wizardStep=0,formError='',search='',filter='All',lessonIndex=0,sidebarOpen=false,sidebarHidden=false,toastTimer,tourStep=-1,priorFocus=null;
const W=()=>state.workspaces.find(w=>w.id===state.wid)||state.workspaces[0];
const ownOffers=()=>state.offers.filter(o=>o.wid===state.wid);
const ownMembers=()=>state.members.filter(m=>m.wid===state.wid);
const ownPosts=()=>state.posts.filter(p=>p.wid===state.wid);
const memberId=()=>`viewer-${state.wid}`;
const scopeTx=()=>state.role==='Agency'?state.transactions:state.transactions.filter(t=>t.wid===state.wid);
const lessonsOf=o=>(o.modules||[]).flatMap((m,mi)=>m.lessons.map((l,li)=>({...l,module:m.title,key:`${mi}-${li}`})));
const log=(action,wid=state.wid)=>state.audit.unshift({id:uuid(),action,wid,time:new Date().toISOString()});
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false}}
function paidAccess(oid,wid=state.wid){return state.transactions.some(t=>t.wid===wid&&t.offeringId===oid&&t.memberId===`viewer-${wid}`&&t.gross>t.refunded&&(!t.expires||new Date(t.expires)>new Date()))}
function hasAccess(o){return o.price===0||paidAccess(o.id,o.wid)||(o.planId&&paidAccess(o.planId,o.wid))}
function commit(message){persist();render();if(message)toast(message)}
function toast(text){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${icon('checkcircle',18)}<span>${esc(text)}</span><button class="iconbtn" ${attrs('dismiss-toast')} aria-label="Dismiss message">${icon('close',15)}</button></div>`;toastTimer=setTimeout(()=>{$('#toast-root').innerHTML=''},6500)}
function pageTo(page){state.page=page;search='';filter='All';sidebarOpen=false;persist();render();window.scrollTo({top:0,behavior:'smooth'})}
function roleTo(role,page){state.role=role;state.page=page||navs[role][0];search='';filter='All';sidebarOpen=false;persist();render();window.scrollTo({top:0,behavior:'smooth'})}
function field(label,name,value='',type='text',hint=''){return `<label class="formfield">${esc(label)}<input type="${type}" name="${esc(name)}" data-field="${esc(name)}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''} autocomplete="off">${hint?`<span class="hint">${esc(hint)}</span>`:''}</label>`}
function textarea(label,name,value='',rows=3,hint=''){return `<label class="formfield">${esc(label)}<textarea name="${esc(name)}" data-field="${esc(name)}" rows="${rows}">${esc(value)}</textarea>${hint?`<span class="hint">${esc(hint)}</span>`:''}</label>`}
function selectField(label,name,options,value){return `<label class="formfield">${esc(label)}<select name="${esc(name)}" data-field="${esc(name)}">${options.map(o=>{const v=typeof o==='string'?o:o.value;const l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function empty(title,text,button=''){return `<div class="empty"><div class="empty-icon">${icon('layers',23)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`}
function stat(label,value,note,ic='activity'){return `<div class="card stat"><div class="stat-label">${esc(label)}${icon(ic,17)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`}
function searchBox(placeholder){return `<div class="searchbox">${icon('search',16)}<input type="search" id="search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(search)}"></div>`}
function statusBadge(s){return badge(s,['Active','Published','Delivered','Paid'].includes(s)?'success':['Suspended','Cancelled','Refunded'].includes(s)?'danger':'')}
function eventDate(o){return o.date?new Date(o.date+'+05:30').toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'})+' IST':'Date to be confirmed'}
const totals=ts=>({gross:ts.reduce((a,t)=>a+t.gross,0),refunds:ts.reduce((a,t)=>a+t.refunded,0),commission:ts.reduce((a,t)=>a+t.commission-t.commissionReversed,0),payable:ts.reduce((a,t)=>a+net(t),0)});
function render(){
 const w=W();if(!state.workspaces.some(x=>x.id===state.wid))state.wid=w.id;
 const title=state.page==='Overview'?(state.role==='Agency'?'Build something that grows.':'Your creator home.'):state.page==='Community'?'Good ideas grow together.':state.page;
 const subtitle=state.role==='Agency'?'The people, workspaces and operations behind COHORT.':w.description;
 $('#app').innerHTML=`<div class="previewbar"><span><span class="dot"></span><b>CLIENT PREVIEW</b><span class="preview-detail"> &nbsp; Explore COHORT with sample data</span></span><button class="textbtn" ${attrs('about')}>About this demo ${icon('info',13)}</button></div><header class="header"><div class="header-left"><button class="iconbtn" ${attrs('toggle-sidebar')} aria-label="Toggle navigation">${icon('menu',20)}</button><div class="brand"><div class="brand-symbol">${icon('layers',24)}</div><div>COHORT<div class="brand-tag">Your audience. Your knowledge. Your business.</div></div></div></div><div class="header-right"><button class="textbtn header-guide" ${attrs('tour')}>${icon('play',13)} Guided walkthrough</button><div class="role-switch" aria-label="Choose a demo perspective">${Object.keys(navs).map(r=>`<button type="button" class="${state.role===r?'active':''}" ${attrs('role',r)} aria-pressed="${state.role===r}">${r}</button>`).join('')}</div><span class="avatar header-avatar">${state.role==='Agency'?'CO':state.role==='Creator'?'CR':'ME'}</span></div></header><div class="layout ${sidebarOpen?'sidebar-open':''} ${sidebarHidden?'no-sidebar':''}"><div class="mobile-nav-shade" ${attrs('toggle-sidebar')}></div><aside class="sidebar" ${sidebarHidden?'style="display:none"':''}><div><div class="eyebrow">${state.role==='Agency'?'Agency console':'Creator workspace'}</div><select class="workspace-picker" id="workspace-picker" aria-label="Demo workspace">${state.workspaces.map(x=>`<option value="${esc(x.id)}" ${x.id===state.wid?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><nav class="nav">${navs[state.role].map(n=>`<button type="button" class="${state.page===n?'active':''}" ${attrs('nav',n)}>${icon(navIcon[n])}${esc(n)}</button>`).join('')}</nav><div class="sidebar-tip">${icon('spark',22)}<h3 style="font-size:12px;margin-top:9px">One platform. Your entire business.</h3><p>Build a community. Share what you know. Create your next opportunity.</p><button class="textbtn" style="margin-top:12px;font-size:11px" ${attrs('tour')}>Explore the journey ${icon('arrow',13)}</button></div><div class="sidebar-footer">COHORT · Product demonstration<br/>India · INR<br/><button class="textbtn" style="font-size:10px;margin-top:8px" ${attrs('about')}>Preview scope & information</button></div></aside><main class="main"><div class="content"><div class="pagehead"><div><div class="breadcrumb">${esc(state.role==='Agency'?'COHORT agency':w.name)} ${icon('chevron',11)} ${esc(state.page)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${state.page==='Overview'&&state.role==='Agency'?btn('Add new creator','new-creator','','','plus'):''}</div>${tourStep>=0?tourBanner():''}${!storageAvailable?'<div class="notice warn" style="margin-bottom:18px">Browser storage is unavailable. Changes will last only while this page remains open. You can export a demo backup from About this demo.</div>':''}<div id="page-body">${state.role!=='Agency'&&w.status!=='Active'?empty(`Workspace ${w.status.toLowerCase()}`,'Use the Agency view to activate the invitation or restore this workspace.',btn('Open agency view','role','Agency','','arrow')):pageContent()}</div><footer class="footer"><span>COHORT · Build your community. Own your audience. Grow your business.</span><span>Client preview · <button class="textbtn" ${attrs('about')}>No real payments</button></span></footer></div></main></div>`;
}
function pageContent(){switch(state.page){case'Overview':return overview();case'Creators':return creators();case'Revenue':case'Earnings':return revenue();case'Packages':return packagesPage();case'Agency services':return services();case'Activity':return activity();case'Community':return community();case'Classroom':return offeringPage('Course');case'Store':return offeringPage('Product');case'Memberships':return offeringPage('Membership');case'Events':return offeringPage('Event');case'Members':return membersPage();case'Settings':return settingsPage();case'My account':return account();default:return overview()}}
function overview(){const w=W(),agency=state.role==='Agency',ts=totals(scopeTx()),of=ownOffers();return `<div class="stack"><section class="hero"><div class="hero-orbits"></div><div class="hero-mark">${icon('layers',120)}</div><div class="hero-content"><div class="eyebrow">${agency?'From first invitation to first sale':'A space for your next chapter'}</div><h2>${agency?'Great creator businesses start here.':`Welcome to ${esc(w.name)}.`}</h2><p>${agency?'Bring creators on board, give their ideas a home, and help them launch. Every workspace is a new possibility.':'Bring your people together. Share what you know, publish your next offering and make every member feel at home.'}</p>${agency?btn('Create a creator workspace','new-creator','','light','plus'):btn('Manage your classroom','nav','Classroom','light','arrow')} ${agency?btn('Take a guided tour','tour','','ghost','play').replace('class="btn ghost"','class="btn ghost" style="color:white"'):''}</div></section><div class="grid">${stat(agency?'Creator workspaces':'Active members',agency?state.workspaces.length:ownMembers().filter(m=>m.status==='Active').length,agency?`${state.workspaces.filter(x=>x.status==='Active').length} active workspaces`:'Members in this workspace','users')}${stat('Gross sales',money(ts.gross),'From simulated purchases only','credit')}${stat(agency?'Net platform commission':'Published offerings',agency?money(ts.commission):of.filter(o=>o.published).length,agency?'After simulated refund adjustments':'Courses, products, plans and events',agency?'activity':'layers')}</div><div class="grid two"><div class="card"><div class="row between"><h3>${agency?'Creator workspaces':'Your launch checklist'}</h3><button class="textbtn" ${attrs('nav',agency?'Creators':'Settings')}>Manage ${icon('up',14)}</button></div><div style="margin-top:13px">${agency?state.workspaces.slice(0,5).map(x=>`<div class="list-row"><span class="avatar large">${esc(x.name.split(' ').filter(y=>y!=='The').map(y=>y[0]).slice(0,2).join(''))}</span><div class="grow"><button class="textbtn" style="text-align:left;color:var(--ink);font-size:13px" ${attrs('open-workspace',x.id)}>${esc(x.name)}</button><div class="meta small muted" style="margin-top:4px">${esc(x.owner)} · ${esc(x.package)}</div></div>${statusBadge(x.status)}</div>`).join(''):[['Workspace activated',w.status==='Active'],['Publish a course or product',of.some(o=>o.published)],['Welcome your first member',ownMembers().some(m=>m.status==='Active')],['Complete a demonstration sale',scopeTx().length>0]].map(([text,done])=>`<div class="list-row">${icon(done?'checkcircle':'circle',19)}<span class="small">${text}</span></div>`).join('')}</div></div><div class="card"><div class="row between"><h3>Your next steps</h3><span class="badge">Start here</span></div><div style="margin-top:13px">${[{n:'01',title:'Create a workspace',sub:'Agency · Creator onboarding',action:'new-creator'},{n:'02',title:'Publish an offering',sub:'Creator · Classroom and store',action:'jump-creator'},{n:'03',title:'Experience a purchase',sub:'Member · Explore and checkout',action:'jump-member'},{n:'04',title:'Follow the earnings',sub:'Agency · Revenue and refunds',action:'jump-revenue'}].map(j=>`<button class="list-button" ${attrs(j.action)}><div class="list-row"><span class="journey-n">${j.n}</span><div class="grow"><div class="title">${j.title}</div><div class="meta">${j.sub}</div></div>${icon('chevron',16)}</div></button>`).join('')}</div></div></div>${state.audit.length?`<div class="card"><div class="row between"><h3>Recent activity</h3>${btn('View activity','jump-activity','','ghost sm','arrow')}</div>${state.audit.slice(0,3).map(l=>`<div class="list-row">${icon('activity',17)}<div class="grow"><div class="title">${esc(l.action)}</div><div class="meta">${esc(state.workspaces.find(x=>x.id===l.wid)?.name||'COHORT')} · ${new Date(l.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</div></div></div>`).join('')}</div>`:''}</div>`}
function creators(){const rows=state.workspaces.filter(x=>`${x.name} ${x.owner}`.toLowerCase().includes(search.toLowerCase()));return `<div class="stack"><div class="filterbar">${searchBox('Search creators or workspaces')}${btn('Add new creator','new-creator','','','plus')}</div><div class="grid three">${rows.map(x=>`<div class="card workspace-card"><div class="row between"><div class="avatar large">${icon('users',22)}</div>${statusBadge(x.status)}</div><h3>${esc(x.name)}</h3><p class="muted small" style="margin-top:5px">${esc(x.owner)}</p><div class="workspace-path">Workspace path: /${esc(x.slug)}</div><hr class="divider"><div class="price-line"><span>Setup package</span><b>${esc(x.package)}</b></div><div class="price-line"><span>Platform subscription</span><b>${money(x.monthly)}/month</b></div><div class="price-line"><span>Transaction commission</span><b>${x.rate}%</b></div><div class="row wrap" style="margin-top:21px">${btn(x.status==='Invited'?'Preview invitation':'Open workspace','open-workspace',x.id,'sm','up')}${btn('Manage','manage-workspace',x.id,'secondary sm')}</div><p class="small muted" style="font-size:9px;margin-top:14px;overflow-wrap:anywhere">Workspace ID: ${esc(x.id)}</p></div>`).join('')}</div>${rows.length?'':empty('No creators found','Try another search or create a new workspace.')}</div>`}
function revenue(){const ts=scopeTx(),t=totals(ts);return `<div class="stack"><div class="grid">${stat('Gross creator sales',money(t.gross),'Total simulated checkout value','credit')}${stat('Net COHORT commission',money(t.commission),'After refund adjustments','activity')}${stat('Creator payable*',money(t.payable),'Before gateway fees and taxes','users')}</div><div class="notice">Demonstration ledger only. No money is collected or transferred. Gateway fees and taxes are not configured. Refunds: <b>${money(t.refunds)}</b>.</div><div class="row between wrap"><h3>Transactions</h3>${btn('Export CSV','export-transactions','','secondary sm','download')}</div>${ts.length?ts.map(x=>`<div class="card"><div class="row between wrap"><div><h3>${esc(x.title)}</h3><p class="muted small" style="margin-top:6px">${esc(state.workspaces.find(w=>w.id===x.wid)?.name)} · ${esc(x.kind)} · ${new Date(x.created).toLocaleDateString('en-IN')}</p></div>${statusBadge(x.refunded===x.gross?'Refunded':x.refunded>0?'Partially refunded':'Demo paid')}</div><div class="finance-row"><div><span>Gross</span><b>${money(x.gross)}</b></div><div><span>Commission (${x.rate}%)</span><b>${money(x.commission-x.commissionReversed)}</b></div><div><span>Refunded</span><b>${money(x.refunded)}</b></div><div><span>Creator payable*</span><b>${money(net(x))}</b></div></div><div class="row between wrap" style="margin-top:17px"><span class="muted small">Settlement: not connected</span>${x.refunded<x.gross?btn('Simulate refund','refund',x.id,'secondary sm'):badge('Access revoked','danger')}</div></div>`).join(''):empty('Your first sale starts the story','Switch to the Member view and purchase a course using demo checkout. The transaction and commission will appear here.',btn('Explore as a member','jump-member','','','arrow'))}<p class="small muted">*Before gateway fees, tax and other adjustments. Full refunds revoke paid access. Partial refunds retain access in this demonstration.</p>${state.role==='Agency'?`<div class="card"><h3>Keep every revenue stream distinct</h3><p class="small muted" style="margin-top:8px">Setup packages and quotations are not recorded as collected revenue. These billing integrations belong to the production build.</p><div class="finance-row"><div><span>Setup fees collected</span><b>${money(0)}</b></div><div><span>SaaS fees collected</span><b>${money(0)}</b></div><div><span>Agency services collected</span><b>${money(0)}</b></div><div><span>Commission</span><b>${money(t.commission)}</b></div></div></div>`:''}</div>`}
function packagesPage(){return `<div class="stack"><div class="filterbar"><p class="small muted">One-time setup packages. Proposed pricing, configurable for each engagement.</p>${btn('New package','new-package','','','plus')}</div><div class="grid">${state.packages.map(p=>`<div class="card">${badge(p.name)}<div class="pkgprice">${money(p.price)}</div><p class="small muted">one-time setup</p><p class="small muted" style="margin:20px 0 25px">${esc(p.description)}</p>${btn('Edit package','edit-package',p.id,'secondary','settings')}</div>`).join('')}</div><div class="notice">A creator’s COHORT platform subscription is separate from setup packages and from memberships sold to their audience. Proposed default: 30 included days, then ₹699/month.</div></div>`}
function services(){return `<div class="stack"><div class="filterbar"><p class="small muted">Manage hands-on services independently from SaaS access.</p>${btn('Create quotation','new-service','','','plus')}</div>${state.jobs.length?`<div class="grid">${state.jobs.map(j=>`<div class="card">${statusBadge(j.status)}<h3 style="margin-top:15px">${esc(j.title)}</h3><p class="small muted" style="margin-top:6px">${esc(state.workspaces.find(x=>x.id===j.wid)?.name)}</p><div class="price" style="margin-top:18px">${money(j.price)}</div><p class="small muted" style="margin-top:12px">Owner: ${esc(j.assignee||'Unassigned')}<br/>Due: ${esc(j.due||'Not set')}</p><p class="small muted" style="margin-top:10px">${esc(j.deliverables||'Deliverables to be agreed.')}</p><div class="row wrap" style="margin-top:17px"><select class="control" data-job="${esc(j.id)}" aria-label="Service status">${['Quotation','Agreed','In progress','Delivered','Cancelled'].map(s=>`<option ${s===j.status?'selected':''}>${s}</option>`).join('')}</select>${btn('Edit','edit-service',j.id,'secondary sm')}</div></div>`).join('')}</div>`:empty('The work behind a successful launch','Create quotations for setup support, content production, community management or growth services.',btn('Create your first quotation','new-service','','','plus'))}</div>`}
function activity(){return `<div class="stack"><div class="row between wrap"><p class="small muted">Activity recorded in this browser, not a server audit trail.</p>${btn('Export activity','export-activity','','secondary sm','download')}</div>${state.audit.length?`<div class="card">${state.audit.map(l=>`<div class="timeline-entry"><p>${esc(l.action)}</p><small>${esc(state.workspaces.find(x=>x.id===l.wid)?.name||'COHORT')} · ${new Date(l.time).toLocaleString('en-IN')}</small></div>`).join('')}</div>`:empty('Your activity will appear here','Onboard a creator, publish content or complete a demo purchase to start the timeline.')}</div>`}
function community(){const posts=ownPosts().filter(p=>filter==='All'||p.category===filter).sort((a,b)=>Number(b.pinned)-Number(a.pinned));return `<div class="stack"><div class="hero" style="min-height:165px;padding:25px 30px"><div class="hero-content"><div class="eyebrow">Your people. Your place.</div><h2>${esc(W().name)}</h2><p style="margin-bottom:0">${ownMembers().filter(m=>m.status==='Active').length} active members · A shared space to learn and grow</p></div><div class="hero-mark">${icon('chat',96)}</div></div><div class="card composer"><div class="row"><div class="avatar">${state.role==='Creator'?'CR':'ME'}</div><div><h3 style="font-size:13px">Start a conversation</h3><p class="small muted" style="font-size:10px">Share a question, an idea or a small win.</p></div></div><textarea id="post-text" aria-label="New community post" placeholder="What would you like to share?"></textarea><div class="row between wrap"><select class="control" id="post-category" style="width:auto" aria-label="Post category"><option>Discussion</option><option>Questions</option><option>Wins</option>${state.role==='Creator'?'<option>Announcements</option>':''}</select>${btn('Publish post','publish-post','','','send')}</div></div><div class="tabs">${['All','Announcements','Discussion','Questions','Wins'].map(c=>`<button class="tab ${filter===c?'active':''}" ${attrs('category',c)}>${c}</button>`).join('')}</div>${posts.length?posts.map(p=>`<article class="card"><div class="row"><div class="avatar">${esc(p.author.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div class="grow"><h3 style="font-size:12px">${esc(p.author)}</h3><p class="small muted" style="font-size:10px">${esc(p.category)} · ${new Date(p.created).toLocaleDateString('en-IN')}</p></div>${p.pinned?badge('Pinned'):''}</div><p class="post-content">${esc(p.text)}</p><div class="post-actions"><button class="textbtn" ${attrs('like',p.id)} style="color:${p.liked?'var(--blue)':'var(--muted)'}">${icon('heart',15)} ${p.likes} ${p.likes===1?'like':'likes'}</button><span class="small muted">${p.comments.length} comments</span>${state.role==='Creator'?`<button class="textbtn" ${attrs('pin',p.id)}>${p.pinned?'Unpin':'Pin'}</button><button class="textbtn muted" ${attrs('remove-post',p.id)}>Remove</button>`:`<button class="textbtn" style="margin-left:auto" ${attrs('report',p.id)}>Report</button>`}</div>${p.comments.map(c=>`<div class="comment"><b>${esc(c.author)}</b>${esc(c.text)}</div>`).join('')}<div class="row" style="margin-top:15px"><input class="control" id="comment-${esc(p.id)}" aria-label="Write a comment" placeholder="Add to the conversation…" maxlength="3000">${btn('Reply','comment',p.id,'secondary sm')}</div></article>`).join(''):empty('Start the conversation','There are no posts in this category yet.')}</div>`}
function offeringPage(kind){const items=ownOffers().filter(o=>o.kind===kind&&(state.role!=='Member'||o.published)&&o.title.toLowerCase().includes(search.toLowerCase()));const text={Course:'Learn at your pace. Put your knowledge to work.',Product:'Useful resources, one simple place.',Membership:'A closer connection to the community.',Event:'Conversations that move you forward.'};return `<div class="stack"><div class="filterbar">${searchBox(`Search ${state.page.toLowerCase()}`)}${state.role==='Creator'?btn(`Create ${kind.toLowerCase()}`,'new-offer',kind,'','plus'):''}</div><p class="small muted">${text[kind]}</p><div class="grid three">${items.map((o,i)=>offeringCard(o,i)).join('')}</div>${items.length?'':empty(`No ${kind.toLowerCase()}s to show`,state.role==='Creator'?'Create and publish an offering to make it available to members.':'This creator has not published an offering here yet.')}</div>`}
function offeringCard(o,i){const access=hasAccess(o),lessons=lessonsOf(o),done=(state.progress[o.id]||[]).filter(k=>lessons.some(l=>l.key===k)).length;const plan=o.planId&&state.offers.find(p=>p.id===o.planId);return `<article class="card coursecard"><div class="course-cover tone-${i%4}"><div class="row between">${icon(kindIcon[o.kind],29)}${badge(o.kind==='Course'?`${lessons.length} lessons`:o.kind==='Membership'?o.period||'Monthly':o.kind==='Event'?'Live workshop':'Digital resource')}</div><div class="cover-label">${esc(W().name)}</div><div class="cover-art"></div></div><div class="coursebody"><div class="row wrap">${state.role==='Creator'?statusBadge(o.published?'Published':'Draft'):access&&o.price>0?badge('Access unlocked','success'):o.price===0?badge('Free to explore'):''}</div><h3>${esc(o.title)}</h3><p class="description">${esc(o.description)}</p>${o.kind==='Event'?`<p class="small muted">${icon('calendar',13)} ${esc(eventDate(o))}</p>`:''}${plan?`<p class="small" style="font-size:10px;color:var(--blue)">Included with ${esc(plan.title)}</p>`:''}${o.kind==='Membership'?`<p class="small muted">${ownOffers().filter(x=>x.planId===o.id).length} included offerings</p>`:''}${state.role==='Member'&&o.kind==='Course'&&done>0?`<div><div class="progress"><div style="width:${lessons.length?done/lessons.length*100:0}%"></div></div><p class="lesson-progress-text">${done} of ${lessons.length} lessons completed</p></div>`:''}<div class="coursefoot"><div class="price">${o.price===0?'Free':money(o.price)}${o.kind==='Membership'?`<small> / ${o.period==='Annual'?'year':o.period==='One-time'?'once':'month'}</small>`:''}</div>${state.role==='Creator'?btn('Manage','edit-offer',o.id,'secondary sm','up'):btn(!access?'Purchase':o.kind==='Course'?(done?'Continue':'Start learning'):o.kind==='Product'?'Download':o.kind==='Event'?(state.registrations.includes(o.id)?'View ticket':'Register'):'View plan','use-offer',o.id,'sm',!access?'lock':'arrow')}</div></div></article>`}
function membersPage(){const rows=ownMembers().filter(m=>`${m.name} ${m.email}`.toLowerCase().includes(search.toLowerCase()));return `<div class="stack"><div class="filterbar">${searchBox('Search community members')}${btn('Invite member','new-member','','','plus')}</div><div class="notice">Member roles and statuses can be explored in this demo. They do not provide real authentication or security.</div>${rows.map(m=>`<div class="card row wrap between"><div class="row"><div class="avatar">${esc(m.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><h3 style="font-size:13px">${esc(m.name)}</h3><p class="small muted">${esc(m.email)}</p></div></div><div class="row wrap">${statusBadge(m.status)}<select class="control" style="width:120px" aria-label="Member role" data-member-role="${esc(m.id)}">${['Admin','Moderator','Member'].map(r=>`<option ${r===m.role?'selected':''}>${r}</option>`).join('')}</select>${btn(m.status==='Suspended'?'Restore':m.status==='Invited'?'Activate':'Suspend','member-status',m.id,'secondary sm')}</div></div>`).join('')}${rows.length?'':empty('No matching members','Invite a member or try another search.')}</div>`}
function settingsPage(){const w=W();return `<div class="stack"><div class="card"><h3>Workspace identity</h3><div class="stack" style="margin-top:20px">${field('Workspace name','settingsName',w.name)}${textarea('Community description','settingsDescription',w.description)}<p class="hint">Preview path: /${esc(w.slug)}. Custom domains and file uploads are part of the production build.</p><div>${btn('Save workspace','save-settings','','','check')}</div></div></div><div class="card"><div class="row between wrap"><h3>Your COHORT subscription</h3>${statusBadge(w.billing)}</div><div class="pkgprice" style="font-size:29px">${money(w.monthly)}<span class="small muted"> / month</span></div><p class="small muted">${w.days} included days from activation. ${w.rate}% commission on eligible transactions.</p><p class="small muted" style="margin:14px 0 19px">This is your platform subscription, separate from memberships your audience buys. Real recurring billing, invoices and reminders are not connected.</p>${btn('Explore billing states','billing',w.id,'secondary','credit')}</div><div class="card"><h3>Workspace information</h3><div class="finance-row"><div><span>Default language</span><b>English</b></div><div><span>Timezone</span><b>Asia/Kolkata</b></div><div><span>Currency</span><b>INR</b></div><div><span>Status</span><b>${esc(w.status)}</b></div></div></div></div>`}
function account(){const ts=state.transactions.filter(t=>t.wid===state.wid&&t.memberId===memberId());return `<div class="stack"><div class="card"><div class="row"><div class="avatar large">ME</div><div><h3>Demo Member</h3><p class="small muted">${esc(W().name)} · Member preview</p></div></div><div class="finance-row"><div><span>Courses started</span><b>${state.enrolled.filter(id=>ownOffers().some(o=>o.id===id&&hasAccess(o))).length}</b></div><div><span>Event registrations</span><b>${state.registrations.filter(id=>ownOffers().some(o=>o.id===id&&hasAccess(o))).length}</b></div><div><span>Purchases</span><b>${ts.length}</b></div></div></div><h3>Purchases and memberships</h3>${ts.length?ts.map(t=>{const cancelled=state.cancelledRenewals.includes(t.offeringId);return `<div class="card"><div class="row between wrap"><div><h3 style="font-size:14px">${esc(t.title)}</h3><p class="small muted" style="margin-top:6px">${money(t.gross)} · ${esc(t.kind)} · ${new Date(t.created).toLocaleDateString('en-IN')}</p></div>${statusBadge(t.refunded===t.gross?'Refunded':t.expires&&new Date(t.expires)<=new Date()?'Expired':cancelled?'Renewal cancelled':'Access active')}</div>${t.kind==='Membership'&&t.refunded<t.gross?`<p class="small muted" style="margin-top:15px">${t.expires?'Demo access ends '+new Date(t.expires).toLocaleDateString('en-IN')+'.':'One-time access.'} No renewal payments are scheduled.</p><div style="margin-top:13px">${btn(cancelled?'Resume renewal':'Cancel renewal','cancel-renewal',t.offeringId,'secondary sm')}</div>`:''}<div style="margin-top:14px">${btn('Download demo receipt','receipt',t.id,'ghost sm','download')}</div></div>`}).join(''):empty('Your next chapter starts here','Explore the classroom or store. Your demonstration purchases will appear here.',btn('Explore the classroom','nav','Classroom','','book'))}<h3>Your event tickets</h3>${state.registrations.filter(id=>ownOffers().some(o=>o.id===id&&hasAccess(o))).map(id=>{const o=state.offers.find(x=>x.id===id);return `<div class="card row between wrap"><div><h3 style="font-size:13px">${esc(o.title)}</h3><p class="small muted">${esc(eventDate(o))}</p></div>${btn('View ticket','ticket',id,'secondary sm','calendar')}</div>`}).join('')||'<p class="small muted">No event registrations yet.</p>'}</div>`}
const tours=[{title:'Start in the agency console',text:'See the two sample creator workspaces. You can add a new creator with a guided onboarding flow.',role:'Agency',page:'Creators'},{title:'Explore the creator’s workspace',text:'Open a course with Manage to see modules, lessons, prices and publication settings.',role:'Creator',page:'Classroom'},{title:'Experience the member journey',text:'Purchase the digital-product course using demo checkout, then start a lesson.',role:'Member',page:'Classroom'},{title:'Follow the sale into the ledger',text:'Inspect the 7% commission, export transactions, or simulate a full or partial refund.',role:'Agency',page:'Revenue'},{title:'Review the community experience',text:'Post a question, react to a welcome post, and explore memberships or events.',role:'Member',page:'Community'}];
function tourBanner(){const t=tours[tourStep];return `<div class="tourbanner"><div><b>Walkthrough ${tourStep+1}/${tours.length}: ${t.title}</b><p>${t.text}</p></div><div class="row">${btn(tourStep===tours.length-1?'Finish walkthrough':'Next step','tour-next','','sm','arrow')}<button class="iconbtn" ${attrs('tour-close')} aria-label="Close walkthrough">${icon('close',15)}</button></div></div>`}
function openModal(type,id='',values={}){priorFocus=document.activeElement;modal={type,id};fields={...values};wizardStep=0;lessonIndex=0;formError='';drawModal();requestAnimationFrame(()=>$('#modal-root input, #modal-root select, #modal-root textarea, #modal-root button')?.focus())}
function closeModal(){modal=null;fields={};formError='';$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(priorFocus&&document.contains(priorFocus))priorFocus.focus()}
function drawModal(){if(!modal)return;document.body.classList.add('modal-open');const titles={'onboard':'Create a creator workspace','invitation':'Your creator invitation','workspace':'Manage creator workspace','offering':`${modal.id?'Edit':'Create'} ${(fields.kind||'offering').toLowerCase()}`,'checkout':'Complete your demo purchase','refund':'Simulate a refund','lesson':state.offers.find(o=>o.id===modal.id)?.title||'Classroom','member':'Invite a community member','package':'Configure setup package','service':modal.id?'Edit agency service':'Create a service quotation','billing':'Explore subscription states','ticket':'Your event registration','plan':'Your membership','about':'Welcome to COHORT','reset':'Reset this demonstration','delete-post':'Remove community post'};$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${['lesson','about'].includes(modal.type)?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">COHORT · ${['about','lesson','plan','ticket'].includes(modal.type)?'Creator business platform':'Interactive demo'}</div><h2 id="modal-title">${esc(titles[modal.type]||'COHORT')}</h2></div><button class="iconbtn" ${attrs('close-modal')} aria-label="Close dialog">${icon('close',21)}</button></div><div class="modal-body">${formError?`<div class="notice error" role="alert">${esc(formError)}</div>`:''}${modalContent()}</div></section></div>`}
function modalContent(){const f=fields,w=W(),o=state.offers.find(x=>x.id===modal.id);switch(modal.type){
case'onboard':return `<div class="wizard-steps">${['Creator identity','Commercial terms','Review & invite'].map((s,i)=>`<div class="${i<=wizardStep?'active':''}">${i+1}. ${s}</div>`).join('')}</div>${wizardStep===0?`${field('Creator name','owner',f.owner)}${field('Email address','email',f.email,'email','Use sample details only. No invitation is sent from this demo.')}${field('Workspace name','name',f.name)}${field('Workspace URL slug','slug',f.slug,'text','Leave blank to generate from the workspace name. Must be unique.')}`:wizardStep===1?`${selectField('Setup package','packageId',state.packages.map(p=>({value:p.id,label:p.name+' · '+money(p.price)})),f.packageId)}<div class="grid">${field('COHORT monthly fee (₹)','monthly',f.monthly,'number')}${field('Included access (days)','days',f.days,'number')}</div>${field('Transaction commission (%)','rate',f.rate,'number')}<div class="notice">These are configurable commercial proposals. No setup payment is collected in this demo.</div>`:`<div class="summarybox"><h3>${esc(f.name)}</h3><p>${esc(f.owner)} · ${esc(f.email)}</p><p>Workspace path: /${esc(f.slug)}</p><hr class="divider"><p>${esc(state.packages.find(p=>p.id===f.packageId)?.name)} setup package</p><p>${money(rupees(f.monthly))}/month after ${esc(f.days)} included days</p><p>${esc(f.rate)}% on eligible transactions</p></div><div class="notice">This creates a demonstration workspace and invitation record. You can preview the invitation and activate the creator experience. No password or real login is involved.</div>`}<div class="modal-foot">${btn(wizardStep?'Back':'Cancel',wizardStep?'onboard-back':'close-modal','','secondary')}${btn(wizardStep<2?'Continue':'Create workspace',wizardStep<2?'onboard-next':'onboard-save','','','arrow')}</div>`;
case'invitation':{const x=state.workspaces.find(t=>t.id===modal.id);return `<div class="hero" style="min-height:160px;padding:25px"><div class="hero-content"><div class="eyebrow">Your next chapter starts here</div><h2>Welcome, ${esc(x.owner)}.</h2><p style="margin-bottom:0">${esc(x.name)} is ready for you to make it your own.</p></div></div><p class="small muted">Prepared for ${esc(x.email)}. This is an invitation preview, not a delivered email. Production will use secure, expiring invitations and verified account setup.</p>${btn('Simulate acceptance & open workspace','accept-invitation',x.id,'full','arrow')}`}
case'workspace':{const x=state.workspaces.find(t=>t.id===modal.id);return `<div class="summarybox"><h3>${esc(x.name)}</h3><p>${esc(x.owner)} · ${esc(x.email)}</p><p>${esc(x.package)} · ${money(x.monthly)}/month · ${x.rate}% commission</p><p class="break">Workspace ID: ${esc(x.id)}</p></div>${selectField('Workspace status','status',['Active','Invited','Suspended'],f.status)}<p class="hint">Workspace status is separate from subscription billing status. Suspension does not remove content or transaction records.</p>${btn('Apply workspace status','save-workspace',x.id,'','check')}`}
case'offering':{const plans=ownOffers().filter(p=>p.kind==='Membership'&&p.id!==modal.id);return `${field('Title','title',f.title)}${textarea('Description','description',f.description)}<div class="grid">${field('Price (₹)','price',f.price,'number','Use 0 for a free offering.')}${selectField('Publication status','published',['Draft','Published'],f.published)}</div>${['Course','Product','Event'].includes(f.kind)?selectField('Also included in membership','planId',[{value:'',label:'No membership inclusion'},...plans.map(p=>({value:p.id,label:p.title}))],f.planId||''):''}${f.kind==='Course'?`${textarea('Modules and lesson titles','curriculum',f.curriculum,7,'Write a module heading beginning with #, then one lesson per line. Example: # Getting started, followed by lesson titles on new lines.')}<p class="hint">Existing lesson text is preserved when titles match. New lessons receive editable demonstration text. Video hosting and secure uploads are not connected.</p>${modal.id&&o?.kind==='Course'?`<details><summary class="textbtn">Edit existing lesson text</summary><div class="stack" style="margin-top:14px">${lessonsOf(o).map(l=>`<label class="formfield">${esc(l.title)}<textarea data-lesson-body="${esc(l.title)}" rows="5">${esc(f.lessonBodies?.[l.title]??l.body)}</textarea></label>`).join('')}</div></details>`:''}`:''}${f.kind==='Membership'?selectField('Billing period','period',['Monthly','Annual','One-time'],f.period||'Monthly'):''}${f.kind==='Event'?`${field('Date and time (India)','date',f.date,'datetime-local')}${field('Duration (minutes)','duration',f.duration||'60','number')}`:''}${f.kind==='Product'?'<div class="notice">Downloads use a demonstration workbook. Protected file uploads and expiring links require backend storage.</div>':''}${btn('Save '+(f.kind||'offering').toLowerCase(),'save-offering','','','check')}`}
case'checkout':return `<div class="summarybox">${badge(o.kind)}<h3 style="font-size:20px;margin-top:13px">${esc(o.title)}</h3><p>By ${esc(w.name)}</p><hr class="divider"><div class="row between"><b>Demo total</b><b>${money(o.price)}</b></div></div>${selectField('Test payment result','outcome',[{value:'success',label:'Successful payment'},{value:'failure',label:'Failed payment'}],f.outcome||'success')}<div class="notice">No card, UPI or bank details are needed. No money will be charged. This demonstrates the checkout outcome, access entitlement and commission record; it is not a payment-provider integration.</div>${btn('Simulate purchase · '+money(o.price),'complete-purchase',o.id,'full','lock')}<p class="hint">Taxes and gateway fees are not configured. Recurring payments are not scheduled.</p>`;
case'refund':return `<p class="small muted">A full refund removes purchased access. A partial refund adjusts commission and retains access in this demo.</p>${field('Refund amount (₹)','amount',f.amount,'number')}<div class="notice">Only the local demonstration ledger changes. No payment provider is contacted.</div>${btn('Record demo refund','save-refund',modal.id,'','refresh')}`;
case'member':return `${field('Member name','name',f.name)}${field('Email address','email',f.email,'email')}${selectField('Role','role',['Member','Moderator','Admin'],f.role||'Member')}<p class="hint">No email is sent. Use fictitious demonstration details.</p>${btn('Create demo invitation','save-member','','','send')}`;
case'package':return `${field('Package name','name',f.name)}${field('One-time setup price (₹)','price',f.price,'number')}${textarea('Included deliverables','description',f.description)}<p class="hint">Changing a package does not alter existing creator agreements.</p>${btn('Save package','save-package','','','check')}`;
case'service':return `${field('Service name','title',f.title)}${selectField('Creator workspace','wid',state.workspaces.map(x=>({value:x.id,label:x.name})),f.wid||state.wid)}<div class="grid">${field('Quote amount (₹)','price',f.price,'number')}${field('Due date','due',f.due,'date')}</div>${field('Assigned to','assignee',f.assignee)}${textarea('Deliverables','deliverables',f.deliverables)}${btn('Save quotation','save-service','','','check')}`;
case'billing':return `<p class="small muted">Explore subscription states without collecting payments. These do not trigger automated reminders or suspension.</p>${selectField('COHORT subscription status','billing',['Included access','Active','Payment failed','Grace period','Cancelled'],f.billing||w.billing)}${btn('Apply demo billing state','save-billing','','','check')}`;
case'lesson':return lessonContent(o);
case'ticket':return `<div class="summarybox">${badge('Registered','success')}<h3 style="font-size:22px;margin-top:15px">${esc(o.title)}</h3><p>${esc(eventDate(o))}</p><p>Hosted by ${esc(w.name)}</p><p>Attendee: Demo Member</p></div><p class="small muted">This is a demonstration registration. No live meeting has been scheduled. You can download a calendar file to inspect the event details.</p><div class="row wrap">${btn('Download calendar event','calendar-download',o.id,'','calendar')}${btn('Cancel registration','unregister',o.id,'secondary')}</div>`;
case'plan':return `<div class="summarybox">${badge(hasAccess(o)?'Membership active':'Explore membership',hasAccess(o)?'success':'')}<h3 style="font-size:22px;margin-top:14px">${esc(o.title)}</h3><p>${esc(o.description)}</p></div><h3>Included offerings</h3>${ownOffers().filter(x=>x.planId===o.id).map(x=>`<div class="row">${icon(kindIcon[x.kind])}<span class="small grow">${esc(x.title)}</span>${badge(x.kind)}</div>`).join('')||'<p class="small muted">No content linked to this plan yet.</p>'}<div class="notice">This demonstration shows membership-based access. Real renewal payments, cancellation notices and expiry jobs need production billing.</div>`;
case'about':return aboutContent();
case'reset':return `<p class="small muted">This will remove all demo changes saved in this browser and restore the two sample workspaces. No external system is affected.</p><div class="notice warn">If you want to keep your demo changes, export a backup first.</div><div class="row wrap">${btn('Export backup','export-backup','','secondary','download')}${btn('Reset demo data','confirm-reset','','danger','refresh')}</div>`;
case'delete-post':return `<p class="small muted">Remove this post and its comments from the demonstration workspace?</p><div class="row">${btn('Cancel','close-modal','','secondary')}${btn('Remove post','confirm-remove-post',modal.id,'danger')}</div>`;
default:return ''}}
function lessonContent(o){if(!o||!hasAccess(o))return '<div class="notice warn">Paid access is no longer available for this course.</div>';const lessons=lessonsOf(o),l=lessons[lessonIndex];if(!l)return '<p class="small muted">This course has no lessons yet.</p>';return `<div class="lesson-layout"><div class="lesson-nav">${lessons.map((x,i)=>`<button class="${i===lessonIndex?'active':''}" ${attrs('lesson-select',String(i))}>${icon((state.progress[o.id]||[]).includes(x.key)?'checkcircle':'play',13)}${esc(x.title)}</button>`).join('')}</div><div><div class="lesson-scene">${icon('book',28)}<div class="eyebrow">${esc(l.module)} · Lesson ${lessonIndex+1}/${lessons.length}</div><h3>${esc(l.title)}</h3></div><div class="lesson-copy">${esc(l.body||'This is a demonstration lesson. Add your own course content during production setup.').replace(/\n\n/g,'</p><p style="margin-top:14px">')}</div><p class="hint" style="margin-top:16px">Illustrative lesson content for product demonstration.</p><div class="modal-foot">${lessonIndex?btn('Previous','lesson-prev','','secondary sm'):''}${btn(lessonIndex===lessons.length-1?'Complete course':'Complete & continue','lesson-complete',o.id,'sm','check')}</div></div></div>`}
function aboutContent(){return `<div class="hero" style="min-height:160px;padding:25px"><div class="hero-content"><div class="eyebrow">One platform. Your entire creator business.</div><h2>A home for your community and your knowledge.</h2><p style="margin-bottom:0">Explore how the COHORT agency, creators and their members work together.</p></div></div><div class="grid two"><div><h3 style="margin-bottom:12px">What you can explore</h3>${['Creator onboarding and workspace activation','Community posts, comments and moderation','Courses with modules, lessons and progress','Digital products and membership access','Events, registration and calendar downloads','Demo checkout, commissions and refunds','Packages, service quotations and exports'].map(x=>`<div class="checkline">${icon('checkcircle',16)}${x}</div>`).join('')}</div><div><h3 style="margin-bottom:12px">What this preview is not</h3>${['Not a hosted production SaaS','No real sign-in or verified invitations','No real payments, taxes or bank settlements','No server-enforced privacy or tenant isolation','No recurring billing or background email jobs','No protected file storage or video hosting'].map(x=>`<div class="checkline">${icon('info',16)}${x}</div>`).join('')}</div></div><div class="notice">All people, communities, content and financial activity are demonstration data. Changes are stored only in this browser where local storage is available. They are not shared with other viewers. Do not enter real passwords, bank details or confidential customer information.</div><div class="row wrap">${btn('Start guided walkthrough','start-tour-modal','','','play')}${btn('Export demo backup','export-backup','','secondary','download')}${btn('Reset demo data','reset','','secondary','refresh')}</div><p class="hint">Standalone HTML application. No installation, account, internet connection or third-party assets are required. Commercial prices are proposals from the supplied planning document, not approved terms.</p>`}
function fail(message){formError=message;drawModal()}
function newCreator(){if(state.role!=='Agency')roleTo('Agency','Creators');openModal('onboard','',{owner:'',email:'',name:'',slug:'',packageId:state.packages[1]?.id||state.packages[0].id,monthly:'699',days:'30',rate:'7'})}
function onboardNext(){try{if(wizardStep===0){if(!fields.owner?.trim()||!fields.name?.trim()||!/^\S+@\S+\.\S+$/.test(fields.email||''))throw new Error('Enter a creator name, workspace name and valid email address.');fields.slug=slugify(fields.slug||fields.name);if(!fields.slug)throw new Error('Enter a URL using letters or numbers.');if(state.workspaces.some(w=>w.slug===fields.slug))throw new Error('This workspace URL is already taken. Choose another one.')}if(wizardStep===1){rupees(fields.monthly);if(!Number.isInteger(Number(fields.days))||Number(fields.days)<0||Number(fields.days)>3650)throw new Error('Included days must be a whole number between 0 and 3650.');if(!fields.rate?.trim()||!Number.isFinite(Number(fields.rate))||Number(fields.rate)<0||Number(fields.rate)>100)throw new Error('Commission must be between 0% and 100%.')}formError='';wizardStep++;drawModal()}catch(e){fail(e.message)}}
function saveCreator(){try{if(state.workspaces.some(w=>w.slug===fields.slug))throw new Error('That URL is already taken.');const p=state.packages.find(x=>x.id===fields.packageId);if(!p)throw new Error('Select a valid setup package.');const id=uuid();state.workspaces.push({id,name:fields.name.trim(),owner:fields.owner.trim(),email:fields.email.trim(),slug:fields.slug,package:p.name,setup:p.price,monthly:rupees(fields.monthly),days:Number(fields.days),rate:Number(fields.rate),status:'Invited',billing:'Included access',description:'Welcome to your new community. Make this space your own.',created:new Date().toISOString()});state.wid=id;state.page='Creators';log('Creator workspace provisioned. Demo invitation prepared.',id);closeModal();commit('Workspace created. Preview its invitation to activate the creator experience.')}catch(e){fail(e.message)}}
function parseCurriculum(text,existing){const old=lessonsOf(existing||{});let modules=[],m;for(const line of String(text||'').split('\n').map(s=>s.trim()).filter(Boolean)){if(line.startsWith('#')){m={title:line.replace(/^#+\s*/,'').trim()||'Module',lessons:[]};modules.push(m)}else{if(!m){m={title:'Getting started',lessons:[]};modules.push(m)}m.lessons.push({title:line,body:old.find(x=>x.title===line)?.body||'This is a demonstration lesson. Add your own course material during production setup.\n\nYour action: write down one useful takeaway from this lesson.'})}}return modules.filter(m=>m.lessons.length)}
function editOffer(id){const o=state.offers.find(x=>x.id===id);openModal('offering',id,{...o,price:String(o.price/100),published:o.published?'Published':'Draft',curriculum:(o.modules||[]).map(m=>'# '+m.title+'\n'+m.lessons.map(l=>l.title).join('\n')).join('\n\n'),duration:String(o.duration||60),lessonBodies:Object.fromEntries(lessonsOf(o).map(l=>[l.title,l.body]))})}
function saveOffer(){try{const f=fields;if(!f.title?.trim())throw new Error('Add an offering title.');const price=rupees(f.price||'0'),existing=state.offers.find(x=>x.id===modal.id),modules=f.kind==='Course'?parseCurriculum(f.curriculum,existing):undefined;if(f.kind==='Course'&&(!modules||!modules.length))throw new Error('Add at least one lesson to this course.');if(f.kind==='Event'&&f.published==='Published'&&!f.date)throw new Error('Add an event date and time before publishing.');if(f.kind==='Event'&&(!Number.isInteger(Number(f.duration||60))||Number(f.duration||60)<1||Number(f.duration||60)>1440))throw new Error('Event duration must be between 1 and 1440 minutes.');if(modules)for(const m of modules)for(const l of m.lessons)if(f.lessonBodies&&Object.prototype.hasOwnProperty.call(f.lessonBodies,l.title))l.body=f.lessonBodies[l.title];const o={id:modal.id||uuid(),wid:state.wid,kind:f.kind,title:f.title.trim(),description:f.description?.trim()||'',price,published:f.published==='Published',planId:f.planId||'',...(modules?{modules}:{}),...(f.kind==='Membership'?{period:f.period||'Monthly'}:{}),...(f.kind==='Event'?{date:f.date||'',duration:Number(f.duration||60),link:''}:{})};if(modal.id)state.offers=state.offers.map(x=>x.id===modal.id?o:x);else state.offers.push(o);if(o.kind==='Course')state.progress[o.id]=[];log(`${o.kind} ${modal.id?'updated':'created'}: ${o.title}`);closeModal();commit('Offering saved. Published content is now available in the member view.')}catch(e){fail(e.message)}}
function useOffer(id){const o=state.offers.find(x=>x.id===id);if(!o||o.wid!==state.wid||!o.published)return toast('This offering is not available.');if(!hasAccess(o))return openModal('checkout',id,{outcome:'success'});if(o.kind==='Course'){state.enrolled=[...new Set([...state.enrolled,id])];persist();openModal('lesson',id);const ls=lessonsOf(o),next=ls.findIndex(l=>!(state.progress[id]||[]).includes(l.key));lessonIndex=Math.max(0,next);drawModal()}else if(o.kind==='Product')downloadProduct(o);else if(o.kind==='Membership')openModal('plan',id);else{if(!state.registrations.includes(id)){state.registrations.push(id);log('Demo event registration: '+o.title);commit()}openModal('ticket',id)}}
function completePurchase(id){try{const o=state.offers.find(x=>x.id===id);if(!o||o.wid!==state.wid||!o.published)throw new Error('This offering is no longer available.');if(W().status!=='Active')throw new Error('This workspace is not active.');if(fields.outcome==='failure')throw new Error('Demo payment failed. No transaction or access was created. Choose a successful outcome to retry.');if(hasAccess(o))throw new Error('This demo member already has access.');const created=new Date();let expires='';if(o.kind==='Membership'&&o.period!=='One-time'){const end=new Date(created);end.setDate(end.getDate()+(o.period==='Annual'?365:30));expires=end.toISOString()}const t={id:uuid(),wid:state.wid,offeringId:o.id,title:o.title,kind:o.kind,gross:o.price,commission:commission(o.price,W().rate),rate:W().rate,refunded:0,commissionReversed:0,created:created.toISOString(),memberId:memberId(),expires};state.transactions.unshift(t);if(o.kind==='Course')state.enrolled=[...new Set([...state.enrolled,o.id])];if(o.kind==='Event')state.registrations=[...new Set([...state.registrations,o.id])];state.cancelledRenewals=state.cancelledRenewals.filter(x=>x!==o.id);log(`Demo purchase: ${o.title} · ${money(o.price)}`);closeModal();commit('Demo purchase complete. Access and earnings are updated. No money was charged.')}catch(e){fail(e.message)}}
function saveRefund(id){try{const t=state.transactions.find(x=>x.id===id);if(!t)throw new Error('Transaction not found.');const amount=rupees(fields.amount);const result=refundTransaction(t,amount);state.transactions=state.transactions.map(x=>x.id===id?result:x);log(`Demo refund: ${money(amount)} for ${t.title}`,t.wid);closeModal();commit(result.refunded===result.gross?'Full refund recorded. Access from this purchase is revoked.':'Partial refund recorded. Commission adjusted; access retained.')}catch(e){fail(e.message)}}
function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csvValue(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportTransactions(){const rows=[['Transaction ID','Workspace','Offering','Type','Gross INR','Refunded INR','Net commission INR','Creator payable before fees/tax INR','Created','Mode'],...scopeTx().map(t=>[t.id,state.workspaces.find(w=>w.id===t.wid)?.name,t.title,t.kind,(t.gross/100).toFixed(2),(t.refunded/100).toFixed(2),((t.commission-t.commissionReversed)/100).toFixed(2),(net(t)/100).toFixed(2),t.created,'DEMO ONLY'])];download('COHORT-demo-transactions.csv','\uFEFF'+rows.map(r=>r.map(csvValue).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Demonstration transactions exported.')}
function downloadProduct(o){if(!hasAccess(o))return toast('Purchase or membership access is required.');download('COHORT-creator-launch-workbook.txt',`COHORT | CREATOR LAUNCH WORKBOOK\nDemonstration resource, not a purchased production file.\n\n${o.title}\nBy ${W().name}\n\n1. YOUR AUDIENCE\nWho are you helping? What is their specific challenge?\n\n2. YOUR OUTCOME\nWhat will someone be able to do after using your product?\n\n3. YOUR FIRST OFFER\nFormat:\nScope:\nPrice hypothesis:\n\n4. YOUR LAUNCH\nMessage 1: Name the problem.\nMessage 2: Explain your approach.\nMessage 3: Invite the next step.\n\n5. YOUR NEXT ACTION\nWhat will you do this week?\n`);toast('Demonstration workbook downloaded.')}
function calendarFile(o){if(!o.date)return toast('An event date has not been set.');const start=new Date(o.date+'+05:30'),end=new Date(start.getTime()+(o.duration||60)*60000),fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//COHORT//Client Demo//EN','BEGIN:VEVENT',`UID:${o.id}@cohort.demo`,`DTSTAMP:${fmt(new Date())}`,`DTSTART:${fmt(start)}`,`DTEND:${fmt(end)}`,`SUMMARY:${safe('[DEMO] '+o.title)}`,`DESCRIPTION:${safe('COHORT demonstration event. No live meeting is scheduled. '+o.description)}`,'STATUS:TENTATIVE','END:VEVENT','END:VCALENDAR'];download('COHORT-demo-event.ics',lines.join('\r\n'),'text/calendar');toast('Demo calendar event downloaded. It is labelled as a demonstration.')}
function saveMember(){try{if(!fields.name?.trim()||!/^\S+@\S+\.\S+$/.test(fields.email||''))throw new Error('Enter a name and a valid email address.');if(ownMembers().some(m=>m.email.toLowerCase()===fields.email.toLowerCase()))throw new Error('That email is already in this workspace.');state.members.push({id:uuid(),wid:state.wid,name:fields.name.trim(),email:fields.email.trim(),role:fields.role||'Member',status:'Invited'});log('Demo member invitation: '+fields.email);closeModal();commit('Member invitation recorded. No email was sent.')}catch(e){fail(e.message)}}
function savePackage(){try{if(!fields.name?.trim())throw new Error('Enter a package name.');if(state.packages.some(p=>p.name.toLowerCase()===fields.name.trim().toLowerCase()&&p.id!==modal.id))throw new Error('A package with that name already exists.');const p={id:modal.id||uuid(),name:fields.name.trim(),description:fields.description||'',price:rupees(fields.price)};if(modal.id)state.packages=state.packages.map(x=>x.id===modal.id?p:x);else state.packages.push(p);log('Setup package saved: '+p.name);closeModal();commit('Package saved. Existing creator agreements are unchanged.')}catch(e){fail(e.message)}}
function saveService(){try{if(!fields.title?.trim())throw new Error('Enter a service name.');const old=state.jobs.find(x=>x.id===modal.id),j={id:modal.id||uuid(),wid:fields.wid,title:fields.title.trim(),price:rupees(fields.price),due:fields.due||'',assignee:fields.assignee||'',deliverables:fields.deliverables||'',status:old?.status||'Quotation'};if(modal.id)state.jobs=state.jobs.map(x=>x.id===modal.id?j:x);else state.jobs.push(j);log('Agency quotation saved: '+j.title,j.wid);closeModal();commit('Agency service quotation saved. No agreement or invoice was sent.')}catch(e){fail(e.message)}}
function action(name,id,el){switch(name){
case'nav':return pageTo(id);
case'role':return roleTo(id);
case'toggle-sidebar':if(window.innerWidth<=720){sidebarHidden=false;sidebarOpen=!sidebarOpen}else sidebarHidden=!sidebarHidden;render();return;
case'dismiss-toast':$('#toast-root').innerHTML='';return;
case'about':return openModal('about');
case'close-modal':return closeModal();
case'new-creator':return newCreator();
case'onboard-next':return onboardNext();
case'onboard-back':wizardStep=Math.max(0,wizardStep-1);formError='';drawModal();return;
case'onboard-save':return saveCreator();
case'open-workspace':{const w=state.workspaces.find(x=>x.id===id);if(!w)return;state.wid=id;if(w.status==='Invited')openModal('invitation',id);else roleTo('Creator');persist();return}
case'accept-invitation':{const w=state.workspaces.find(x=>x.id===id);w.status='Active';state.wid=id;log('Demo creator invitation accepted.',id);closeModal();roleTo('Creator');toast('Creator workspace activated for this demonstration.');return}
case'manage-workspace':{const w=state.workspaces.find(x=>x.id===id);return openModal('workspace',id,{status:w.status})}
case'save-workspace':{const w=state.workspaces.find(x=>x.id===id);w.status=fields.status;log('Workspace status updated: '+w.status,id);closeModal();commit('Workspace status updated. Content and financial records have been retained.');return}
case'jump-creator':roleTo('Creator','Classroom');return;
case'jump-member':roleTo('Member','Classroom');return;
case'jump-revenue':roleTo('Agency','Revenue');return;
case'jump-activity':roleTo('Agency','Activity');return;
case'new-package':return openModal('package','',{name:'',price:'0',description:''});
case'edit-package':{const p=state.packages.find(x=>x.id===id);return openModal('package',id,{name:p.name,price:String(p.price/100),description:p.description})}
case'save-package':return savePackage();
case'new-service':return openModal('service','',{title:'',price:'7500',wid:state.wid,due:'',assignee:'',deliverables:''});
case'edit-service':{const j=state.jobs.find(x=>x.id===id);return openModal('service',id,{...j,price:String(j.price/100)})}
case'save-service':return saveService();
case'new-offer':return openModal('offering','',{kind:id,title:'',description:'',price:'0',published:'Draft',curriculum:'# Getting started\nIntroduction\nYour next steps',planId:'',period:'Monthly',date:'',duration:'60'});
case'edit-offer':return editOffer(id);
case'save-offering':return saveOffer();
case'use-offer':return useOffer(id);
case'complete-purchase':return completePurchase(id);
case'refund':{const t=state.transactions.find(x=>x.id===id);return openModal('refund',id,{amount:String((t.gross-t.refunded)/100)})}
case'save-refund':return saveRefund(id);
case'export-transactions':return exportTransactions();
case'export-activity':download('COHORT-demo-activity.csv','\uFEFF'+[['Time','Workspace','Action'],...state.audit.map(l=>[l.time,l.wid,l.action])].map(r=>r.map(csvValue).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Demo activity exported.');return;
case'publish-post':{const text=$('#post-text')?.value?.trim();if(!text)return toast('Write a message before publishing.');if(text.length>10000)return toast('Please keep the post under 10,000 characters.');const category=$('#post-category').value;state.posts.unshift({id:uuid(),wid:state.wid,author:state.role==='Creator'?W().owner:'Demo Member',text,pinned:false,likes:0,liked:false,comments:[],category,created:new Date().toISOString()});filter='All';log('Community post published.');commit('Your post is now visible in this workspace.');return}
case'category':filter=id;render();return;
case'like':{const p=state.posts.find(x=>x.id===id);p.liked=!p.liked;p.likes+=p.liked?1:-1;commit();return}
case'pin':{const p=state.posts.find(x=>x.id===id);p.pinned=!p.pinned;log(`Community post ${p.pinned?'pinned':'unpinned'}.`);commit();return}
case'report':log('Community post reported for review: '+id);commit('Report recorded in the local demo activity log.');return;
case'remove-post':return openModal('delete-post',id);
case'confirm-remove-post':state.posts=state.posts.filter(x=>x.id!==id);log('Community post removed.');closeModal();commit('Post removed.');return;
case'comment':{const p=state.posts.find(x=>x.id===id),text=document.getElementById('comment-'+id)?.value?.trim();if(!text)return toast('Write a comment first.');p.comments.push({author:state.role==='Creator'?W().owner:'Demo Member',text});commit('Comment added.');return}
case'new-member':return openModal('member','',{name:'',email:'',role:'Member'});
case'save-member':return saveMember();
case'member-status':{const m=state.members.find(x=>x.id===id);m.status=m.status==='Suspended'||m.status==='Invited'?'Active':'Suspended';log('Member status updated: '+m.name+' → '+m.status);commit('Member status updated in the demo.');return}
case'save-settings':{const name=$('[data-field="settingsName"]').value.trim();if(!name)return toast('Enter a workspace name.');W().name=name;W().description=$('[data-field="settingsDescription"]').value.trim();log('Workspace identity updated.');commit('Workspace details saved in this browser.');return}
case'billing':return openModal('billing',id,{billing:W().billing});
case'save-billing':W().billing=fields.billing;log('Demo SaaS billing status: '+fields.billing);closeModal();commit('Subscription status updated. Workspace status is unchanged.');return;
case'lesson-select':lessonIndex=Number(id);drawModal();return;
case'lesson-prev':lessonIndex=Math.max(0,lessonIndex-1);drawModal();return;
case'lesson-complete':{const o=state.offers.find(x=>x.id===id);if(!o||!hasAccess(o))return fail('Access is no longer available.');const ls=lessonsOf(o),l=ls[lessonIndex];state.progress[id]=[...new Set([...(state.progress[id]||[]),l.key])];persist();if(lessonIndex<ls.length-1){lessonIndex++;drawModal()}else{log('Course completed: '+o.title);closeModal();commit('Course completed. Your progress is saved in this browser.')}return}
case'cancel-renewal':{if(state.cancelledRenewals.includes(id))state.cancelledRenewals=state.cancelledRenewals.filter(x=>x!==id);else state.cancelledRenewals.push(id);log('Demo membership renewal preference changed.');commit('Demo renewal preference updated. Current access is retained; no payment was scheduled.');return}
case'ticket':return openModal('ticket',id);
case'calendar-download':return calendarFile(state.offers.find(x=>x.id===id));
case'unregister':state.registrations=state.registrations.filter(x=>x!==id);log('Demo event registration cancelled.');closeModal();commit('Registration cancelled. A paid purchase, if any, is not automatically refunded.');return;
case'receipt':{const t=state.transactions.find(x=>x.id===id);download('COHORT-demo-receipt.txt',`COHORT DEMONSTRATION RECEIPT\nNOT A TAX INVOICE OR PROOF OF REAL PAYMENT\n\nTransaction: ${t.id}\nDate: ${t.created}\nWorkspace: ${W().name}\nOffering: ${t.title}\nAmount: ${money(t.gross)}\nRefunded: ${money(t.refunded)}\n\nNo funds were charged, collected or transferred.\n`);toast('Demo receipt downloaded. It is not a tax invoice.');return}
case'tour':tourStep=0;roleTo(tours[0].role,tours[0].page);return;
case'start-tour-modal':closeModal();tourStep=0;roleTo(tours[0].role,tours[0].page);return;
case'tour-next':if(tourStep<tours.length-1){tourStep++;roleTo(tours[tourStep].role,tours[tourStep].page)}else{tourStep=-1;render();toast('Walkthrough complete. Continue exploring any view.')}return;
case'tour-close':tourStep=-1;render();return;
case'export-backup':download('COHORT-demo-backup.json',JSON.stringify({product:'COHORT',notice:'DEMONSTRATION DATA ONLY. Not a production backup.',exported:new Date().toISOString(),state},null,2),'application/json');toast('Demo data backup downloaded for reference. This preview does not import backups.');return;
case'reset':return openModal('reset');
case'confirm-reset':state=seed();tourStep=-1;search='';filter='All';closeModal();commit('Demo reset to its original sample data.');return;
default:toast('This action is unavailable in the preview.');
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;try{action(el.dataset.action,el.dataset.id||'',el)}catch(error){if(modal)fail(error.message||'Something went wrong.');else toast(error.message||'Something went wrong. Please try again.')}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.lessonBody){fields.lessonBodies=fields.lessonBodies||{};fields.lessonBodies[el.dataset.lessonBody]=el.value}if(el.dataset.field)fields[el.dataset.field]=el.value;if(el.id==='search'){search=el.value;const start=el.selectionStart;$('#page-body').innerHTML=pageContent();const next=$('#search');next?.focus();try{next?.setSelectionRange(start,start)}catch{}}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.field){fields[el.dataset.field]=el.value;if(el.dataset.field==='outcome'&&formError){formError='';drawModal()}}if(el.id==='workspace-picker'){state.wid=el.value;search='';filter='All';commit()}if(el.dataset.job){const j=state.jobs.find(x=>x.id===el.dataset.job);j.status=el.value;log('Agency service status: '+j.title+' → '+j.status,j.wid);commit('Service status updated.')}if(el.dataset.memberRole){const m=state.members.find(x=>x.id===el.dataset.memberRole);m.role=el.value;log('Member role changed: '+m.name+' → '+m.role);commit('Demo member role updated.')}});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const elements=[...document.querySelectorAll('#modal-root button:not([disabled]), #modal-root input, #modal-root textarea, #modal-root select, #modal-root a')].filter(x=>x.offsetParent!==null);if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
persist();render();
